#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>
using namespace std;

#define ALL(v) (v).begin(), (v).end()

int dim, limit;
vector<vector<int>> capacity;
vector<vector<int>> adj_list;
vector<int> level, iter;

void add_edge(int u, int v, int cap) {
    adj_list[u].push_back(v);
    adj_list[v].push_back(u);
    capacity[u][v] = cap;
}

bool bfs(int src, int dst) {
    fill(ALL(level), -1);
    queue<int> q;
    level[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj_list[u]) {
            if (level[v] == -1 && capacity[u][v] > 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[dst] != -1;
}

int dfs(int u, int dst, int flow) {
    if (u == dst) return flow;
    for (int& i = iter[u]; i < adj_list[u].size(); ++i) {
        int v = adj_list[u][i];
        if (level[v] == level[u] + 1 && capacity[u][v] > 0) {
            int f = dfs(v, dst, min(flow, capacity[u][v]));
            if (f > 0) {
                capacity[u][v] -= f;
                capacity[v][u] += f;
                return f;
            }
        }
    }
    return 0;
}

int dinic_flow(int src, int dst) {
    int result = 0;
    while (bfs(src, dst)) {
        fill(ALL(iter), 0);
        int f;
        while ((f = dfs(src, dst, INT_MAX)) > 0) {
            result += f;
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> dim >> limit;

    int total = 2 * dim * dim + 2;
    capacity.assign(total, vector<int>(total, 0));
    adj_list.resize(total);
    level.resize(total);
    iter.resize(total);

    vector<string> sci(dim), cap_str(dim);
    int vert[dim][dim][2];
    int bad_pos = -1;

    int node_cnt = 2;
    for (int i = 0; i < dim; ++i) {
        cin >> sci[i];
        for (int j = 0; j < dim; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                int nd = node_cnt++;
                add_edge(0, nd, sci[i][j] - '0');
                vert[i][j][0] = nd;
            } else if (sci[i][j] == 'Z') {
                bad_pos = 100 * i + j;
                sci[i][j] = 'Y';
            }
        }
    }

    int max_node = node_cnt;
    for (int i = 0; i < dim; ++i) {
        cin >> cap_str[i];
        for (int j = 0; j < dim; ++j) {
            if (cap_str[i][j] >= '1' && cap_str[i][j] <= '9') {
                int nd = max_node++;
                add_edge(nd, 1, cap_str[i][j] - '0');
                vert[i][j][1] = nd;
            }
        }
    }

    int dist_from_bad[dim][dim];
    for (int i = 0; i < dim; ++i)
        fill(dist_from_bad[i], dist_from_bad[i] + dim, limit + 1);
    if (bad_pos != -1) {
        dist_from_bad[bad_pos/100][bad_pos%100] = 0;
        queue<int> q;
        q.push(bad_pos);
        int dx[4] = {1, 0, -1, 0};
        int dy[4] = {0, 1, 0, -1};
        while (!q.empty()) {
            int pos = q.front(); q.pop();
            int x = pos/100, y = pos%100;
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (nx >= 0 && nx < dim && ny >= 0 && ny < dim &&
                    sci[nx][ny] != 'Y' && dist_from_bad[nx][ny] > dist_from_bad[x][y] + 1) {
                    dist_from_bad[nx][ny] = dist_from_bad[x][y] + 1;
                    q.push(100 * nx + ny);
                }
            }
        }
    }

    int dx[4] = {1, 0, -1, 0};
    int dy[4] = {0, 1, 0, -1};

    for (int i = 0; i < dim; ++i) {
        for (int j = 0; j < dim; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                int reach[dim][dim];
                for (int x = 0; x < dim; ++x)
                    fill(reach[x], reach[x] + dim, limit + 1);
                reach[i][j] = 0;

                if (cap_str[i][j] >= '1' && cap_str[i][j] <= '9') {
                    int u = vert[i][j][0], v = vert[i][j][1];
                    add_edge(u, v, INT_MAX);
                    add_edge(v, u, INT_MAX);
                }

                queue<int> q;
                q.push(100 * i + j);
                while (!q.empty()) {
                    int pos = q.front(); q.pop();
                    int x = pos / 100, y = pos % 100;
                    for (int k = 0; k < 4; ++k) {
                        int nx = x + dx[k], ny = y + dy[k];
                        if (nx >= 0 && nx < dim && ny >= 0 && ny < dim &&
                            sci[nx][ny] != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                            if (cap_str[nx][ny] >= '1' && cap_str[nx][ny] <= '9') {
                                if (reach[x][y] + 1 <= dist_from_bad[nx][ny]) {
                                    add_edge(vert[i][j][0], vert[nx][ny][1], INT_MAX);
                                    add_edge(vert[nx][ny][1], vert[i][j][0], INT_MAX);
                                }
                            }
                            if (reach[x][y] + 1 < dist_from_bad[nx][ny]) {
                                reach[nx][ny] = reach[x][y] + 1;
                                q.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << dinic_flow(0, 1) << '\n';

    return 0;
}
